// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    __RecordingToken token;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
        token = new __RecordingToken();
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 warpDelta, address targetContract) public {
        amount = bound(amount, 1, 2 ** 128);
        unlockTime = bound(unlockTime, 0, 2 ** 64);
        warpDelta = bound(warpDelta, 1, 2 ** 64);
        vm.assume(targetContract != address(c) && targetContract != address(token));

        // configure flash governance (configured == false, so no proposal check triggers)
        c.configureFlashGovernance(address(token), amount, unlockTime, false);

        // make the test contract a permitted governance actor
        address[] memory governables = new address[](1);
        governables[0] = address(this);
        bool[] memory flags = new bool[](1);
        flags[0] = true;
        c.setGoverned(governables, flags);

        // deposit the flash-governance stake under (targetContract, this)
        c.assertGovernanceApproved(address(this), targetContract, false);

        // pass the unlock deadline
        vm.warp(block.timestamp + unlockTime + warpDelta);

        // first withdrawal pays out exactly the deposited amount
        c.withdrawGovernanceAsset(targetContract, address(token));
        uint256 paidAfterFirst = token.paid(address(this));

        // second withdrawal attempt: the record must already be cleared,
        // so it cannot pay out again (it reverts in the reference)
        try c.withdrawGovernanceAsset(targetContract, address(token)) {
            // in the reference this branch is unreachable; in the mutant it pays again
        } catch {
            // expected in the reference
        }

        assertTrue(
            token.paid(address(this)) <= paidAfterFirst && token.paid(address(this)) <= amount,
            "withdrawal may pay out the deposited amount at most once"
        );
    }
}

contract __RecordingToken {
    mapping(address => uint256) public paid;

    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return type(uint256).max; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function transfer(address to, uint256 amt) external returns (bool) { paid[to] += amt; return true; }
    receive() external payable {}
    fallback() external payable {}
}

